# Ratgeber (nur AT): „Kreditkarte als Student in Österreich“. Gebühren, Versicherungsstufen und Konditionen kommen
# live aus den Kartendaten; Altersgrenzen und Regeln nach dem Studium stammen von den Anbieterseiten (Stand Oktober 2026).
# Abgrenzung zur Bestenliste „Studium“ (Rangfolge, „beste Karte“): dieser Ratgeber erklärt Bonität ohne Einkommen,
# Konditionen nach dem Studium, Auslandssemester und Fallen; er verlinkt auf die Bestenliste statt sie zu wiederholen.
# Aufruf aus ratgeber.build('at'): register(art,P,best,K,nprv,eur,KM)
import html
E=lambda s: html.escape(str(s)) if s is not None else ''
TIERN={0:'keine',1:'Basis',2:'mit Reiserücktritt',3:'umfassend',4:'Premium'}

def _tbl(head,rows):
    h=''.join(f'<th>{c}</th>' for c in head)
    b=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)
    return f'<div class="tbl wide"><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>'

# Studentenkarten: slug | Wer bekommt sie (laut Anbieter) | Was nach dem Studium passiert | Konto nötig
STUD=[
 ('easybank-gold-student','Alle unter 27 mit Hauptwohnsitz in Österreich, kein Studiennachweis; nur mit dem easy gratis Konto; Rahmen 1.000 € bei Einkommen bis 500 €, sonst 3.000 €','Ab dem 27. Geburtstag Kartenentgelt laut Preisblatt','ja'),
 ('diners-club-student','Studierende, Vergabe bonitätsabhängig; Einkaufsrahmen bis 1.500 €; Altersgrenze auf der Anbieterseite nicht genannt','Nicht auf der Anbieterseite genannt','nein'),
 ('bank-austria-gold-student','Studierende, längstens bis zum 30. Geburtstag, nur Hauptkarte; Konto bei der Bank Austria','Umstellung auf die reguläre Gold-Karte liegt nahe; Zeitpunkt und Entgelt nennt der Anbieter nicht','ja'),
 ('bawag-gold-student','Studierende mit BAWAG-Konto und Studiennachweis','Im Monat nach dem 27. Geburtstag wird das Konto auf Standardkonditionen umgestellt, die Karte kostet dann laut Preisblatt des neuen Kontomodells','ja'),
 ('card-complete-student','Studierende bis zum Studienende, längstens bis zum vollendeten 30. Lebensjahr; Vergabe bonitätsabhängig','Nicht auf der Anbieterseite genannt','nein'),
 ('paylife-goldplus-student-maturant','Studierende und Maturantinnen und Maturanten; Altersgrenze im Preisblatt nicht genannt','Nicht im Preisblatt genannt','nein'),
]
GRATIS=['tf-bank-mastercard-gold','advanzia-bank-free-mastercard-gold','santander-card','n26-standard','revolut-standard','wise-karte','trade-republic-karte','card-complete-prepaid']

def register(art,P,best,K,nprv,eur,KM):
    T={c['slug']:c for c in K}
    for s,*_ in STUD:
        if s not in T: raise SystemExit(f'ratgeber_studenten: unbekannte Karte {s}')
    def L(slug,label=None): return f'<a class="lnk" href="{P}at/kreditkarten/{slug}/">{E(label or T[slug]["titel"])}</a>'
    def fee(c):
        f=c.get('fee'); t='kostenlos' if f==0 else (f'{eur(f)} €' if f is not None else 'keine Angabe')
        if c.get('fee1') is not None and c.get('fee1')!=f: t+=f' <small>(1. Jahr {"gratis" if c["fee1"]==0 else eur(c["fee1"])+" €"})</small>'
        return t
    def ins(c): return TIERN.get(c.get('tier'),'keine Angabe') if c.get('tier') is not None else 'keine Angabe'
    typ={'Kreditkarte':'Kreditkarte mit Rahmen','Charge':'Charge-Karte','Debit':'Debitkarte','Prepaid':'Prepaid'}
    stud=_tbl(['Karte','Jahresgebühr','Wer sie bekommt','Nach dem Studium','Reiseversicherung','Zahlung Ausland','Bargeld'],
              [(L(s),fee(T[s]),E(w),E(n),E(ins(T[s])),E(KM.fxT(T[s])),E(KM.cashT(T[s]))) for s,w,n,k in STUD])
    gratis=_tbl(['Karte','Typ','Jahresgebühr','Bonitätsprüfung','Zahlung Ausland','Bargeld','Reiseversicherung'],
                [(L(s),E(typ.get(T[s]['typ'],T[s]['typ'])),fee(T[s]),E('ja, Kreditrahmen' if T[s]['typ']=='Kreditkarte' else ('nein, Guthaben' if T[s]['typ'] in ('Debit','Prepaid') else 'ja')),E(KM.fxT(T[s])),E(KM.cashT(T[s])),E(ins(T[s]))) for s in GRATIS])
    studium=f'{best}studium/'
    art('at','kreditkarte-studenten',
      h1='Kreditkarte als Student in Österreich: Was du ohne Einkommen bekommst und was nach dem Studium passiert',
      mt='Kreditkarte als Student in Österreich: Bonität, Gratis-Karten, Auslandssemester | Finvallo',
      desc='Kreditkarte als Student in Österreich: Karten ohne Einkommen, Studentenkarten der Banken, was nach dem Studium gilt und was im Auslandssemester zählt.',
      lede='Sechs Banken haben eigene Studentenkarten, acht Karten sind für alle gratis. Welche passt, hängt an drei Fragen: Konto, Einkommen und Reisen.',
      kurz=(f'In Österreich gibt es Studentenkarten von easybank, Diners Club, Bank Austria, BAWAG, card complete und PayLife, meist zum halben Preis der normalen Karte und oft nur zusammen mit dem Studentenkonto der Bank. '
            f'Die {L("easybank-gold-student")} ist bis 27 komplett gratis, ohne Studiennachweis, mit Reiseversicherung, verlangt aber das easy gratis Konto. '
            f'Ohne Kontowechsel und ohne Altersgrenze gibt es {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-free-mastercard-gold")} mit Kreditrahmen und Reiseversicherung, allerdings nur nach Bonitätsprüfung, sowie die Debitkarten von N26, Revolut, Wise und Trade Republic ganz ohne Bonitätsprüfung. '
            f'Was danach passiert, steht selten im Prospekt: Bei BAWAG und easybank endet der Studententarif mit 27, bei Bank Austria und card complete spätestens mit 30. Die Rangfolge aller Karten für Studierende zeigt die <a class="lnk" href="{studium}">Bestenliste Studium</a>.'),
      secs=[
       ('Drei Fragen, bevor du dich für eine Karte entscheidest','''<div class="prose"><p><b>1. Willst du das Konto wechseln?</b> Die Studentenkarten der Hausbanken gibt es nur zusammen mit dem Konto derselben Bank. easybank, BAWAG und Bank Austria verlangen das ausdrücklich; die Karte wird vom Konto abgebucht, und das günstige Studentenkonto ist der Grund, warum die Karte wenig oder nichts kostet. Wer sein Konto behalten will, nimmt eine Karte ohne Kontobindung. Diners Club, card complete und PayLife ziehen den Betrag per Einzug von jedem beliebigen Konto ein. Bei TF Bank, Advanzia und Santander überweist du die Rechnung selbst.</p>
<p><b>2. Hast du ein regelmäßiges Einkommen?</b> Echte Kreditkarten mit Kreditrahmen prüfen deine Bonität. Ohne Einkommen fällt der Rahmen klein aus oder der Antrag wird abgelehnt. Debitkarten (N26, Revolut, Wise, Trade Republic) und Prepaid-Karten brauchen keine Prüfung, weil du nur ausgeben kannst, was am Konto liegt. Für Hotels und Mietwagen reicht das aber oft nicht, dazu unten mehr.</p>
<p><b>3. Reist du?</b> Die Studentenkarten der Hausbanken und die beiden Gratis-Kreditkarten enthalten eine Reiseversicherung mit Reiserücktritt und Arztkosten im Ausland. Die Debitkarten der Neobanken in ihrer Gratis-Stufe nicht. Für ein Auslandssemester ist das der Punkt, der am meisten Geld wert ist.</p></div>'''),
       ('Die Studentenkarten der Banken im Vergleich','<p class="note">Sortiert nach Jahresgebühr. „Wer sie bekommt“ und „Nach dem Studium“ stammen von den Anbieterseiten und Preisblättern, Stand Oktober 2026; wo ein Anbieter nichts nennt, steht das so. Aktionen für das erste Jahr sind in Klammern vermerkt.</p>'+stud+
        f'''<div class="prose"><p>Auffällig ist, was fehlt. Nur easybank und BAWAG sagen klar, wann der Studententarif endet (mit 27). Bank Austria und card complete nennen eine Obergrenze von 30 Jahren. Diners Club und PayLife nennen auf ihren Seiten weder Altersgrenze noch Folgekonditionen. Rechne bei allen damit, dass die Karte nach dem Studium zur regulären Variante wird: {L("bawag-gold")} kostet {eur(T["bawag-gold"]["fee"])} € statt {eur(T["bawag-gold-student"]["fee"])} €, {L("easybank-kreditkarte-gold")} {eur(T["easybank-kreditkarte-gold"]["fee"])} € statt 0 €, {L("bank-austria-gold")} {eur(T["bank-austria-gold"]["fee"])} € statt {eur(T["bank-austria-gold-student"]["fee"])} €, {L("paylife-goldplus")} {eur(T["paylife-goldplus"]["fee"])} € statt {eur(T["paylife-goldplus-student-maturant"]["fee"])} €. Ein Kalendereintrag zum 27. oder 30. Geburtstag spart dir die Überraschung auf der Abrechnung.</p>
<p>Die Gebühren bei Fremdwährung und Bargeld sind bei den Studentenkarten dieselben wie bei den teuren Schwestern: 1,5 bis 3,15 % außerhalb des Euroraums und rund 3 % für Bargeld. Günstig sind sie also nur in der Jahresgebühr, nicht im Ausland.</p>
<p class="note"><a class="lnk" href="{studium}">Bestenliste: alle Karten für Studierende und junge Leute, nach Sternen sortiert →</a></p></div>'''),
       ('Karten ohne Studentenstatus, die trotzdem nichts kosten','<p class="note">Karten ohne Jahresgebühr, die jeder beantragen kann. „Bonitätsprüfung ja“ heißt: Die Bank prüft Einkommen und KSV, bevor sie einen Kreditrahmen vergibt.</p>'+gratis+
        f'''<div class="prose"><p>Für die meisten Studierenden ist eine Kombination am günstigsten: eine Debitkarte für den Alltag und das Ausland (N26, Revolut oder Wise, alle ohne Bonitätsprüfung und ohne Fremdwährungsentgelt) plus eine Gratis-Kreditkarte mit Rahmen für Kaution, Flug und Versicherung. {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-free-mastercard-gold")} vergeben den Rahmen nach Bonität; ein Werkstudentenjob oder ein regelmäßiger Eingang helfen. Beide verzinsen Bargeld ab dem Behebungstag, Einkäufe sind bis zu 51 (TF Bank) beziehungsweise 49 Tage (Advanzia) zinsfrei, wenn du die Rechnung vollständig zahlst. Die {L("santander-card")} ist die Ausnahme ohne Reiseversicherung, dafür mit 1 % Cashback bis 50 € im Jahr und kostenlosem Bargeld.</p>
<p>Die {L("card-complete-prepaid")} ist der Weg, wenn die Bonitätsprüfung scheitert: Guthaben aufladen, weltweit zahlen, zwei Behebungen im Monat gratis. Die Jahresgebühr von {eur(T["card-complete-prepaid"]["fee"])} € ist der Preis dafür, dass niemand deine Bonität prüft.</p></div>'''),
       ('Bonität ohne Einkommen: was die Bank prüft und was du tun kannst','''<div class="prose"><p>Jede echte Kreditkarte ist ein Kredit, und vor einem Kredit fragt die Bank den KSV1870 ab und schaut auf dein Einkommen. Studierende haben dabei drei Nachteile: kein oder unregelmäßiges Einkommen, kurze Kontohistorie und oft eine Wohnadresse, die sich jedes Jahr ändert. Das führt nicht automatisch zur Ablehnung, aber zu einem kleinen Rahmen. easybank sagt es offen: bis 500 € Einkommen gibt es 1.000 € Rahmen, darüber 3.000 €.</p>
<p>Was hilft: ein Konto mit regelmäßigem Eingang, auch wenn es nur Familienbeihilfe, Stipendium oder Unterhalt ist; keine offenen Raten oder Mahnungen; die Karte bei der Bank beantragen, bei der das Konto schon länger läuft. Ein Vermerk beim KSV1870 lässt sich einmal im Jahr kostenlos abfragen, bevor du einen Antrag stellst. Was die Prüfung genau umfasst und wie lange sie dauert, steht im Ratgeber <a href="../kreditkarte-beantragen/">Kreditkarte beantragen</a>; welche Karten es ganz ohne KSV-Abfrage gibt, im Ratgeber <a href="../ohne-bonitaetspruefung/">Kreditkarte ohne KSV-Abfrage</a>.</p>
<p>Zwei Dinge solltest du nicht tun: mehrere Anträge gleichzeitig stellen, weil jede Anfrage beim KSV vermerkt werden kann, und einen Rahmen nehmen, den du nicht in einem Monat zurückzahlen könntest. Die Teilzahlung bei TF Bank und Advanzia kostet rund 25 % im Jahr; warum sie so teuer ist, erklärt der Ratgeber <a href="../teilzahlung/">Teilzahlung</a>.</p></div>'''),
       ('Auslandssemester: was die Karte können muss',f'''<div class="prose"><p>Fünf Monate Erasmus in Lissabon, Stockholm oder Krakau stellen andere Anforderungen als ein Wochenende in Wien. Drei Dinge entscheiden:</p><ul>
<li><b>Fremdwährung.</b> In Schweden, Polen, Tschechien, der Schweiz oder Großbritannien zahlst du mit einer Hausbank-Studentenkarte 1,5 bis 3,15 % Aufschlag auf jeden Einkauf. Bei 600 € Ausgaben im Monat sind das über fünf Monate 45 bis 95 €. Karten ohne Fremdwährungsentgelt (TF Bank, Advanzia, N26, Revolut, Wise, Trade Republic) zahlen 0 %. Im Euroraum spielt das keine Rolle.</li>
<li><b>Bargeld.</b> Die Debitkarten der Neobanken beheben innerhalb ihrer Limits gratis, TF Bank und Advanzia gebührenfrei mit Zinsen ab dem Behebungstag, die Hausbank-Karten verlangen rund 3 % plus Fremdwährung. Alle Zahlen stehen im Ratgeber <a href="../bargeld-beheben/">Bargeld beheben</a>.</li>
<li><b>Reiseversicherung über die ganze Dauer.</b> Die Kartenversicherungen gelten pro Reise meist 90 Tage, bei Revolut Premium und Metal nur 30. Ein Semester dauert länger. Diners Club verlängert den Schutz laut Anbieterseite mit Inskriptionsbestätigung auf sechs Monate; die Erste-Karten versichern 180 Tage. Bei den anderen endet der Schutz nach 90 Tagen, und bei Advanzia kann laut Bedingungen die ganze Reise unversichert sein, wenn sie die Höchstdauer überschreitet. Für ein Auslandssemester brauchst du deshalb entweder eine Karte mit langer Deckung oder eine eigene Auslandskrankenversicherung; die e-card deckt im EU-Ausland nur die medizinisch notwendige Versorgung zu den Regeln des Gastlands, keinen Rücktransport. Welche Karte was versichert, steht im Ratgeber <a href="../reiseversicherung/">Reiseversicherung über die Kreditkarte</a>.</li></ul>
<p>Praktisch heißt das: Debitkarte von N26, Revolut oder Wise für Alltag und Bargeld, dazu eine Kreditkarte für die Kaution der Wohnung oder des Mietwagens und als Reserve, und für die Krankenversicherung die Bedingungen der Karte auf die Dauer prüfen, bevor du fliegst.</p></div>'''),
       ('Hotel, Mietwagen, Festival-Ticket: wann eine Debitkarte nicht reicht','''<div class="prose"><p>Debitkarten der Neobanken funktionieren fast überall wie Kreditkarten, mit einer Ausnahme: Wer eine Kaution reservieren will, verlangt oft eine echte Kreditkarte mit Rahmen. Autovermieter lehnen Debit- und Prepaid-Karten häufig ab oder verlangen eine teure Zusatzversicherung; manche Hotels blockieren bei Debitkarten den Betrag sofort auf dem Konto, statt ihn nur zu reservieren. Für den Roadtrip nach dem Semester brauchst du also eine Kreditkarte mit Rahmen, und der Rahmen muss die Kaution abdecken, meist 300 bis 1.500 €. Mit einem 500-Euro-Rahmen wird das knapp. Was die Vermieter genau verlangen, steht im Ratgeber <a href="../mietwagen-kaution/">Mietwagen und Kaution</a>.</p></div>'''),
       ('Die vier Fallen bei Studentenkarten','''<div class="prose"><ol>
<li><b>Die Umstellung nach dem Studium.</b> Aus 0 € werden 59,88 €, aus 30,76 € werden 67,92 €, ohne dass du etwas unterschreibst. Trag dir den Geburtstag ein, an dem der Tarif endet, und entscheide vorher, ob du die Karte zum neuen Preis behalten willst.</li>
<li><b>Die Teilzahlung.</b> Kreditkarten mit Rahmen bieten an, nur einen Teil der Rechnung zu zahlen. Was übrig bleibt, kostet 20 bis 25 % im Jahr. Immer die volle Rechnung zahlen oder den Einzug auf „gesamter Betrag“ stellen.</li>
<li><b>Bargeld mit der Kreditkarte.</b> Bei Hausbank-Karten rund 3 %, mindestens 3,50 bis 4 €, bei TF Bank und Advanzia Zinsen ab dem ersten Tag. Für Bargeld die Bankomatkarte oder die Debitkarte nehmen.</li>
<li><b>Das Konto hinter der Karte.</b> Studentenkonten sind gratis, bis die Bank sie umstellt; danach kosten Konto und Karte zusammen schnell 100 € im Jahr. Die Karte allein zu vergleichen reicht nicht, das Konto gehört dazu.</li></ol></div>'''),
       ('Quellen','''<div class="prose"><ul>
<li>Jahresgebühren, Gebühren im Ausland, Bargeld und Versicherungsstufen: Preisblätter und Bedingungen der Anbieter, verlinkt auf jeder Kartenseite; die Werte werden beim Bauen dieser Seite aus den Kartendaten übernommen.</li>
<li>Altersgrenzen, Studiennachweis und Regeln nach dem Studium: Produktseiten von easybank (easy gratis Konto für Studierende), card complete (Studenten-Card), Diners Club (Student Card), Bank Austria und BAWAG (Konditionenübersicht Kreditkarten) sowie das PayLife-Preisblatt, abgerufen im Oktober 2026.</li></ul></div>'''),
      ],
      faq=[
       ('Bekomme ich als Student eine Kreditkarte ohne Einkommen?','Eine echte Kreditkarte mit Rahmen nur nach Bonitätsprüfung, und ohne Einkommen fällt der Rahmen klein aus oder der Antrag wird abgelehnt. Ohne Prüfung bekommst du Debitkarten von N26, Revolut, Wise oder Trade Republic und Prepaid-Karten wie die card complete Prepaid; sie funktionieren im Alltag wie Kreditkarten, aber nicht immer für Kautionen.'),
       ('Welche Kreditkarte ist für Studenten in Österreich kostenlos?','Die easybank Gold Student ist bis 27 gratis, ohne Studiennachweis, aber nur mit dem easy gratis Konto. Ohne Kontobindung sind TF Bank Mastercard Gold, Advanzia free Mastercard Gold und Santander Card dauerhaft gebührenfrei. BAWAG Gold Student und card complete Student waren zuletzt im ersten Jahr gratis; die Aktionen stehen auf den Kartenseiten.'),
       ('Was passiert mit der Studentenkarte nach dem Studium?','Bei easybank und BAWAG endet der Studententarif im Monat nach dem 27. Geburtstag, dann gilt das Preisblatt der normalen Karte (59,88 € bei easybank Gold, 67,92 € bei BAWAG Gold). Bank Austria und card complete setzen die Grenze bei 30. Diners Club und PayLife nennen auf ihren Seiten keine Regel; nachfragen lohnt sich.'),
       ('Brauche ich für die Studentenkarte ein Konto bei der Bank?','Bei easybank, BAWAG und Bank Austria ja, die Karte gibt es nur zum Konto. Diners Club, card complete und PayLife buchen von jedem Konto ab, ebenso TF Bank, Advanzia und Santander.'),
       ('Welche Karte ist fürs Auslandssemester am besten?','Außerhalb des Euroraums eine Karte ohne Fremdwährungsentgelt: N26, Revolut oder Wise für Alltag und Bargeld, dazu TF Bank oder Advanzia als Kreditkarte mit Reiseversicherung. Beachte die Dauer der Versicherung: meist 90 Tage pro Reise, bei Diners Club mit Inskriptionsbestätigung sechs Monate, bei den Erste-Karten 180 Tage.'),
       ('Zählt eine Kreditkarte als Student zum KSV?','Jede Kreditkarte mit Rahmen wird beim KSV1870 vermerkt, auch die Studentenkarte. Das ist kein Nachteil, solange du pünktlich zahlst; es baut sogar eine Historie auf. Mehrere Anträge kurz hintereinander und offene Raten wirken dagegen negativ.'),
       ('Reicht eine Debitkarte für Hotel und Mietwagen?','Für Hotels meistens, wobei manche den Betrag sofort abbuchen statt zu reservieren. Für Mietwagen oft nicht: Viele Vermieter verlangen eine Kreditkarte mit Rahmen für die Kaution von 300 bis 1.500 €.'),
       ('Was ist besser für Studenten: Kreditkarte oder Debitkarte?','Beides, für verschiedene Zwecke. Die Debitkarte (N26, Revolut, Wise) für Alltag, Ausland und Bargeld, ohne Bonitätsprüfung und ohne Zinsrisiko. Die Kreditkarte (TF Bank, Advanzia oder die Studentenkarte der Hausbank) für Kaution, Flugbuchung und Reiseversicherung. Wer nur eine will und wenig reist, kommt mit der Debitkarte aus.'),
      ],
      related=['kostenlose-kreditkarte','kreditkarte-beantragen','bargeld-beheben'])
